#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


# Sign in with Google and Apple: the Google Cloud and Apple Developer setup a Spindle server needs, and the settings it
# produces (Auth__Google__* and Auth__Apple__*). For Spindle Cloud and for your own server alike; see
# docs/self-hosting.md#sign-in-with-google-and-apple. Run it from anywhere: scripts/setup-sign-in.sh
#
# The values go to deploy/.env (git-ignored), which docker-compose.yml passes to the app. Another file:
#   ENV_FILE=path/to/file scripts/setup-sign-in.sh

cd "$(dirname "$0")/.."
[[ "$ENV_FILE" == ".env" ]] && ENV_FILE="deploy/.env"

TOTAL_STAGES=11

banner "Sign in with Google and Apple"

# ── 1 ──────────────────────────────────────────────────────────────────────
stage "Your server"
say "Google and Apple send people back to your server's address, so everything below is for one address."
ask SPINDLE_BASE_URL "Server address (Enter for https://app.spindletrack.com):"
SPINDLE_BASE_URL="${SPINDLE_BASE_URL:-https://app.spindletrack.com}"
SPINDLE_BASE_URL="${SPINDLE_BASE_URL%/}"
SPINDLE_HOST="${SPINDLE_BASE_URL#https://}"; SPINDLE_HOST="${SPINDLE_HOST%%/*}"
# The registrable domain, e.g. spindletrack.com for app.spindletrack.com (good enough for the usual two-part domains).
SPINDLE_DOMAIN=$(awk -F. '{ if (NF >= 2) print $(NF-1) "." $NF; else print $0 }' <<<"$SPINDLE_HOST")
GOOGLE_CALLBACK="$SPINDLE_BASE_URL/api/auth/external/google/callback"
APPLE_CALLBACK="$SPINDLE_BASE_URL/api/auth/external/apple/callback"
if [[ "$SPINDLE_BASE_URL" != https://* ]]; then
  warn "Apple accepts only https addresses. Google allows http://localhost for development; use a separate client for it."
fi
say ""
note "Google will come back to  $GOOGLE_CALLBACK"
note "Apple will come back to   $APPLE_CALLBACK"
note "Values are saved to       $ENV_FILE"
say ""
DO_GOOGLE=yes; DO_APPLE=yes
confirm "Set up Google?" || DO_GOOGLE=no
confirm "Set up Apple?" || DO_APPLE=no

# ── 2 ──────────────────────────────────────────────────────────────────────
stage "Google Cloud: a project"
if [[ "$DO_GOOGLE" == yes ]]; then
  say "Sign-in needs a Google Cloud project to hold the OAuth client. It's free: no billing account."
  open_url "https://console.cloud.google.com/projectcreate"
  step "Project name: Spindle. Organization: yours, or No organization."
  step "Create, then make sure the new project is selected in the project picker at the top."
  pause "Done? Press Enter."
else
  note "Skipped: Google isn't being set up."; pause
fi

# ── 3 ──────────────────────────────────────────────────────────────────────
stage "Google: what people see when they sign in"
if [[ "$DO_GOOGLE" == yes ]]; then
  open_url "https://console.cloud.google.com/auth/overview"
  step "If it says Google Auth Platform not configured yet, click Get started."
  step "App name: Spindle. User support email: an address people can write to."
  step "Audience: External."
  step "Contact information: your email. Agree to the policy, then Create."
  say ""
  open_url "https://console.cloud.google.com/auth/branding"
  step "App logo: the Spindle mark, 120×120 PNG (optional; a logo needs Google's brand check, see stage 4)."
  step "Application home page: https://$SPINDLE_DOMAIN"
  step "Privacy policy link and Terms of service link: your pages for them."
  step "Authorized domains: $SPINDLE_DOMAIN (add ${SPINDLE_HOST} too if Google asks)."
  step "Save."
  say ""
  open_url "https://console.cloud.google.com/auth/audience"
  step "Publishing status: click Publish app, then Confirm, so it says In production."
  note "In Testing, only the test users you list could sign in."
  note "Spindle asks only for openid, email and profile, so there's no security review and nothing to add under Data access."
  pause "Done? Press Enter."
else
  note "Skipped: Google isn't being set up."; pause
fi

# ── 4 ──────────────────────────────────────────────────────────────────────
stage "Google: prove the domain is yours"
if [[ "$DO_GOOGLE" == yes ]]; then
  say "Google shows your app's name and logo only after it checks that $SPINDLE_DOMAIN is yours."
  open_url "https://search.google.com/search-console/welcome"
  step "Choose Domain, enter $SPINDLE_DOMAIN, Continue."
  step "Copy the TXT record Google shows and add it at your DNS provider for $SPINDLE_DOMAIN."
  step "Back in Search Console, click Verify (DNS can take a few minutes)."
  note "Use the same Google account as in Google Cloud, so the console knows the domain is verified."
  say ""
  open_url "https://console.cloud.google.com/auth/verification"
  step "In Verification Center, submit the branding for verification if it offers to."
  note "Google's check takes a few working days. Sign-in works meanwhile, only without the logo."
  pause "Done (or DNS still on its way)? Press Enter."
else
  note "Skipped: Google isn't being set up."; pause
fi

# ── 5 ──────────────────────────────────────────────────────────────────────
stage "Google: the OAuth client"
if [[ "$DO_GOOGLE" == yes ]]; then
  open_url "https://console.cloud.google.com/auth/clients/create"
  step "Application type: Web application. Name: Spindle."
  step "Authorized JavaScript origins: leave empty."
  step "Authorized redirect URIs → Add URI:"
  say "      $GOOGLE_CALLBACK"
  step "Create. Google shows the client ID and the client secret."
  note "For development, make a second client with http://localhost:5173/api/auth/external/google/callback."
  ask Auth__Google__ClientId "Paste the Client ID (…apps.googleusercontent.com):"
  ask_secret Auth__Google__ClientSecret "Paste the Client secret:"
  if [[ "$Auth__Google__ClientId" != *.apps.googleusercontent.com ]]; then
    warn "That doesn't look like a Google client ID; check it before deploying."
  fi
  write_env Auth__Google__ClientId "$Auth__Google__ClientId"
  write_env Auth__Google__ClientSecret "$Auth__Google__ClientSecret"
  pause
else
  note "Skipped: Google isn't being set up."; pause
fi

# ── 6 ──────────────────────────────────────────────────────────────────────
stage "Apple: an App ID that groups sign-in"
if [[ "$DO_APPLE" == yes ]]; then
  say "Sign in with Apple hangs off a primary App ID. A new one just for this leaves the apps' own App IDs and"
  say "provisioning profiles untouched."
  open_url "https://developer.apple.com/account/resources/identifiers/add/bundleId"
  step "App IDs → Continue → App → Continue."
  step "Description: Spindle. Bundle ID: Explicit, e.g. com.spindletrack.signin.primary"
  step "Capabilities: tick Sign In with Apple (Enable as a primary App ID). Continue → Register."
  ask APPLE_PRIMARY_APP_ID "The Bundle ID you registered:"
  pause
else
  note "Skipped: Apple isn't being set up."; pause
fi

# ── 7 ──────────────────────────────────────────────────────────────────────
stage "Apple: the Services ID (the web sign-in)"
if [[ "$DO_APPLE" == yes ]]; then
  open_url "https://developer.apple.com/account/resources/identifiers/add/serviceId"
  step "Description: Spindle (people see it when they sign in). Identifier: e.g. com.spindletrack.signin"
  step "Continue → Register. Then open the new Services ID from the list."
  step "Tick Sign In with Apple → Configure:"
  say "      Primary App ID: $APPLE_PRIMARY_APP_ID"
  say "      Domains and Subdomains: $SPINDLE_HOST"
  say "      Return URLs: $APPLE_CALLBACK"
  step "Next → Done → Continue → Save."
  ask Auth__Apple__ServicesId "The Services ID identifier:"
  open_url "https://developer.apple.com/account#MembershipDetailsCard"
  step "Membership details show the Team ID (Spindle's is 9ARDA688G5)."
  ask Auth__Apple__TeamId "Team ID:"
  write_env Auth__Apple__ServicesId "$Auth__Apple__ServicesId"
  write_env Auth__Apple__TeamId "$Auth__Apple__TeamId"
  pause
else
  note "Skipped: Apple isn't being set up."; pause
fi

# ── 8 ──────────────────────────────────────────────────────────────────────
stage "Apple: the key the server signs with"
if [[ "$DO_APPLE" == yes ]]; then
  open_url "https://developer.apple.com/account/resources/authkeys/add"
  step "Key name: Spindle Sign in with Apple. Tick Sign in with Apple → Configure → Primary App ID: $APPLE_PRIMARY_APP_ID → Save."
  step "Continue → Register → Download. Apple lets you download the .p8 file only once: keep it in your password manager."
  step "The page shows the Key ID (10 characters)."
  ask Auth__Apple__KeyId "Key ID:"
  APPLE_P8=""
  while [[ ! -f "$APPLE_P8" ]]; do
    ask APPLE_P8 "Path to the downloaded AuthKey_….p8 (drag it here):"
    APPLE_P8="${APPLE_P8%\'}"; APPLE_P8="${APPLE_P8#\'}"; APPLE_P8="${APPLE_P8% }"
    APPLE_P8="${APPLE_P8/#\~/$HOME}"
    [[ -f "$APPLE_P8" ]] || warn "No file at $APPLE_P8; try again."
  done
  if ! grep -q "BEGIN PRIVATE KEY" "$APPLE_P8"; then
    warn "That file doesn't look like a .p8 key."
  fi
  # One line, its line breaks written as \n, as one-line settings (Coolify, .env) need.
  Auth__Apple__PrivateKey=$(awk 'BEGIN { ORS = "\\n" } { sub(/\r$/, ""); print }' "$APPLE_P8")
  Auth__Apple__PrivateKey="${Auth__Apple__PrivateKey%\\n}"
  write_env Auth__Apple__KeyId "$Auth__Apple__KeyId"
  write_env Auth__Apple__PrivateKey "$Auth__Apple__PrivateKey"
  pause
else
  note "Skipped: Apple isn't being set up."; pause
fi

# ── 9 ──────────────────────────────────────────────────────────────────────
stage "Apple: email to hidden addresses"
if [[ "$DO_APPLE" == yes ]]; then
  say "People can hide their address from you; Apple then gives Spindle one like …@privaterelay.appleid.com."
  say "Apple forwards mail to it only from senders you register, so confirmation and trial emails must come from one."
  ask SMTP_FROM "The address Spindle sends from (Smtp__FromAddress):"
  open_url "https://developer.apple.com/account/resources/services/configure"
  step "Sign in with Apple for Email Communication → Configure (or +)."
  step "Add the email address $SMTP_FROM, or its domain ${SMTP_FROM#*@}."
  step "Register. Apple checks the domain's SPF record; your mail provider's DKIM and SPF setup covers it."
  note "Without this, people who hide their address get no email from Spindle. Everything else still works."
  pause "Done? Press Enter."
else
  note "Skipped: Apple isn't being set up."; pause
fi

# ── 10 ─────────────────────────────────────────────────────────────────────
stage "Give the settings to the server"
SETTINGS=$(grep -E '^Auth__(Google|Apple)__' "$ENV_FILE" 2>/dev/null || true)
if [[ -z "$SETTINGS" ]]; then
  warn "Nothing was saved to $ENV_FILE, so there is nothing to give the server."
  pause
else
  say "The server needs these settings: $(cut -d= -f1 <<<"$SETTINGS" | tr '\n' ' ')"
  say ""
  say "On your own server with deploy/docker-compose.yml: they are in $ENV_FILE already."
  step "Run: docker compose -f deploy/docker-compose.yml up -d"
  say ""
  say "On Coolify (Spindle Cloud):"
  if command -v pbcopy >/dev/null 2>&1 && confirm "Copy the settings to the clipboard?"; then
    printf '%s\n' "$SETTINGS" | pbcopy
    note "Copied. They include secrets: paste them once, then copy something else."
  else
    note "Copy the Auth__Google__ and Auth__Apple__ lines from $ENV_FILE."
  fi
  step "Coolify → Spindle → Environment Variables → Developer view → paste at the end → Save."
  step "Deploy a version that has Google and Apple sign-in (merged to main), or Redeploy if it's out already."
  pause "Deployed? Press Enter to check the server."
  PROVIDERS=$(curl -fsS "$SPINDLE_BASE_URL/api/server" 2>/dev/null | grep -o '"name":"[a-z]*"' | cut -d'"' -f4 | tr '\n' ' ' || true)
  if [[ -n "$PROVIDERS" ]]; then
    printf '  %s✓ %s offers:%s %s\n' "$GREEN" "$SPINDLE_BASE_URL" "$RESET" "$PROVIDERS"
  else
    warn "$SPINDLE_BASE_URL/api/server doesn't list Google or Apple yet. Check the settings and that the new version runs."
    SKIPPED+=("Check that $SPINDLE_BASE_URL/api/server lists signInProviders after deploying")
  fi
  pause
fi

# ── 11 ─────────────────────────────────────────────────────────────────────
stage "Try it, and tell people"
open_url "$SPINDLE_BASE_URL/login"
step "Continue with Google, and with Apple, in a private window: each should come back signed in."
step "Try one with Hide My Email on Apple, and check the new account gets email (e.g. a password link)."
step "Privacy policy: say that people can sign in with Google or Apple, and that Spindle then gets their name"
say "    and email address from them, nothing else."
note "If Google shows an error about redirect_uri_mismatch, the URI in stage 5 differs from the server's address."
pause "Done? Press Enter."

finish
